mapper.select:
SELECT  FROM market_observation
WHERE indicator = #{indicator} AND observed_on BETWEEN #{date} AND #{today}
    AND available_at <= #{now}
ORDER BY observed_on DESC LIMIT 60

mapper.update:
UPDATE market_observation SET observed_value = #{value}, source = #{source},
    fetched_at = #{fetchedAt}, available_at = #{availableAt}
WHERE indicator = #{indicator} AND observed_on = #{date}
